// The printables inventory (docs/PRINTABLES_INVENTORY.md, PRINTABLES_SPEC 8): every item in the set by category
// and grade, so whoever adds printables sees what exists. Generated by `node tools/printables.mjs --inventory`;
// a unit test fails when the committed file is out of date. Pure: no I/O.

import { buildWorkbook } from "../../engine/index.js";
import { CATEGORIES, GRADE_ORDER, GRADE_LABELS, activitiesOf } from "./printables_manifest.mjs";

const cell = (s) => String(s).replace(/\|/g, "\\|");

/** @param {object[]} items  printablesSet(catalog)  @param {object} catalog  @returns {string} Markdown */
export function inventoryMarkdown(items, catalog) {
  const rows = items.map((it) => {
    const [student, key] = buildWorkbook(it.script, catalog).documents;
    return { it, pages: student.pages.length, keyPages: key.pages.length, activities: activitiesOf(it.script) };
  });
  const out = [
    "# Printables inventory",
    "",
    "Generated by `node tools/printables.mjs --inventory` from `tools/lib/printables_set.mjs`; do not edit by hand. See [PRINTABLES_SPEC.md](PRINTABLES_SPEC.md) for the taxonomy and how items are made. Before adding a printable, search this list for its skill, topic or activity; to add one, add an entry to the set (or to the education catalog it reads), run `npm run printables:inventory`, and rebuild the set.",
    "",
    `${items.length} items, ${rows.reduce((s, r) => s + r.pages, 0)} student pages, ${rows.filter((r) => r.keyPages).length} answer keys.`,
    "",
    "| Category | " + GRADE_ORDER.map((g) => GRADE_LABELS[g]).join(" | ") + " | Total |",
    "|---|" + GRADE_ORDER.map(() => "---|").join("") + "---|",
    ...CATEGORIES.map((c) => `| ${c.label} | ${GRADE_ORDER.map((g) => rows.filter((r) => r.it.category === c.id && r.it.grade === g).length).join(" | ")} | ${rows.filter((r) => r.it.category === c.id).length} |`),
    "",
  ];
  for (const c of CATEGORIES) {
    const inCat = rows.filter((r) => r.it.category === c.id);
    if (!inCat.length) continue;
    out.push(`## ${c.label} (\`${c.id}\`)`, "");
    for (const g of GRADE_ORDER) {
      const list = inCat.filter((r) => r.it.grade === g).sort((a, b) => (a.it.id < b.it.id ? -1 : 1));
      if (!list.length) continue;
      out.push(`### ${GRADE_LABELS[g]}`, "", "| Id | Title | Strand | Pages | Key | Activities | Skills |", "|---|---|---|---|---|---|---|");
      for (const r of list) out.push(`| \`${r.it.id}\` | ${cell(r.it.title)} | ${r.it.strand} | ${r.pages} | ${r.keyPages ? r.keyPages : "–"} | ${r.activities.join(", ")} | ${r.it.skills.join(", ") || "–"} |`);
      out.push("");
    }
  }
  return out.join("\n");
}
